package de.corporate.lc.imports.service;
import de.corporate.lc.imports.api.*; import de.corporate.lc.lc.domain.*; import de.corporate.lc.lc.repository.*; import de.corporate.lc.lc.service.*; import de.corporate.lc.swift.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class SwiftImportService {
 private static final java.util.regex.Pattern FIELD=java.util.regex.Pattern.compile("(?m)^:(\\d{2}[A-Z]?):(.*?)(?=^:\\d{2}[A-Z]?:|\\z)",java.util.regex.Pattern.DOTALL);
 private static final Map<String,String> LABELS=Map.ofEntries(Map.entry("20","Documentary Credit Number"),Map.entry("23","Reference to Pre-Advice"),Map.entry("26E","Amendment Number"),Map.entry("27","Sequence"),Map.entry("30","Amendment Date"),Map.entry("31C","Date of Issue"),Map.entry("31D","Expiry Date and Place"),Map.entry("31E","New Expiry Date and Place"),Map.entry("32B","Currency and Amount"),Map.entry("33B","Decrease of Amount"),Map.entry("40A","Form of Credit"),Map.entry("41A","Available With"),Map.entry("42C","Drafts at"),Map.entry("44A","Place of Taking in Charge"),Map.entry("44B","Place of Final Destination"),Map.entry("44C","Latest Date of Shipment"),Map.entry("45A","Description of Goods"),Map.entry("46A","Documents Required"),Map.entry("46B","Documents Changed"),Map.entry("47A","Additional Conditions"),Map.entry("48","Period for Presentation"),Map.entry("49","Confirmation Instructions"),Map.entry("50","Applicant"),Map.entry("57A","Advise Through Bank"),Map.entry("59","Beneficiary"),Map.entry("71B","Charges"),Map.entry("78","Instructions to Bank"));
 private static final Map<String,String> TARGETS=Map.ofEntries(Map.entry("20","reference"),Map.entry("26E","amendmentNumber"),Map.entry("30","amendmentDate"),Map.entry("31C","issueDate"),Map.entry("31D","expiryDateAndPlace"),Map.entry("31E","newExpiryDateAndPlace"),Map.entry("32B","amountAndCurrency"),Map.entry("33B","amountDecrease"),Map.entry("44C","latestShipmentDate"),Map.entry("46A","requiredDocuments"),Map.entry("46B","changedDocuments"),Map.entry("50","applicant"),Map.entry("57A","advisingBank"),Map.entry("59","beneficiary"));
 private static final Map<String,String> TARGET_LABELS=Map.ofEntries(Map.entry("reference","LC-Referenz"),Map.entry("amendmentNumber","Amendment-Nummer"),Map.entry("amendmentDate","Amendment-Datum"),Map.entry("issueDate","Ausstellungsdatum"),Map.entry("expiryDateAndPlace","Ablaufdatum und -ort"),Map.entry("newExpiryDateAndPlace","Neues Ablaufdatum und -ort"),Map.entry("amountAndCurrency","Betrag und Währung"),Map.entry("amountDecrease","Betragsreduzierung"),Map.entry("latestShipmentDate","Spätester Versand"),Map.entry("requiredDocuments","Erforderliche Dokumente"),Map.entry("changedDocuments","Geänderte Dokumente"),Map.entry("applicant","Applicant"),Map.entry("advisingBank","Advising Bank"),Map.entry("beneficiary","Beneficiary"));
 private final Mt700Parser mt700;private final Mt707Parser mt707;private final LetterOfCreditRepository lcs;private final AmendmentRepository amendments;private final LetterOfCreditService lcService;private final AmendmentService amendmentService;private final SwiftImportHistoryService history;
 public SwiftImportService(Mt700Parser p700,Mt707Parser p707,LetterOfCreditRepository l,AmendmentRepository a,LetterOfCreditService ls,AmendmentService as,SwiftImportHistoryService h){mt700=p700;mt707=p707;lcs=l;amendments=a;lcService=ls;amendmentService=as;history=h;}
 public SwiftImportPreview preview(SwiftImportRequest request){String raw=requireRaw(request),type=detect(raw);List<SwiftFieldView> fields=fields(raw);List<String> errors=new ArrayList<>(),warnings=new ArrayList<>();try{if(type.equals("MT707")){var p=mt707.parse(raw);Amendment a=p.amendment();Optional<LetterOfCredit> lc=lcs.findByReference(p.lcReference());if(lc.isEmpty())errors.add("Kein Original-Akkreditiv mit dieser Referenz gefunden.");if(a.getAmendmentNumber()==null||a.getAmendmentNumber().isBlank())errors.add("Pflichtfeld :26E: (Amendment-Nummer) fehlt.");boolean duplicate=lc.isPresent()&&a.getAmendmentNumber()!=null&&amendments.existsByLetterOfCreditIdAndAmendmentNumber(lc.get().getId(),a.getAmendmentNumber());if(duplicate)errors.add("Dieses Amendment wurde bereits importiert.");if(a.getAmendmentDate()==null)warnings.add("Feld :30: (Amendment-Datum) fehlt.");return new SwiftImportPreview(type,p.lcReference(),null,null,a.getAmountIncrease(),null,a.getAmendmentDate(),a.getNewExpiryDate(),a.getNewExpiryPlace(),a.getAmendmentNumber(),List.of(),duplicate,errors.isEmpty(),errors,warnings,fields);}LetterOfCredit lc=mt700.parse(raw);if(lc.getExpiryDate()==null)errors.add("Pflichtfeld :31D: (Ablaufdatum) fehlt.");if(lc.getAmount()==null||lc.getCurrency()==null)errors.add("Pflichtfeld :32B: (Währung und Betrag) fehlt.");if(lc.getApplicant()==null)warnings.add("Feld :50: (Applicant) fehlt.");if(lc.getBeneficiary()==null)warnings.add("Feld :59: (Beneficiary) fehlt.");boolean duplicate=lcs.existsByReference(lc.getReference());if(duplicate)errors.add("Ein Akkreditiv mit dieser Referenz existiert bereits.");return new SwiftImportPreview(type,lc.getReference(),lc.getApplicant(),lc.getBeneficiary(),lc.getAmount(),lc.getCurrency(),lc.getIssueDate(),lc.getExpiryDate(),lc.getExpiryPlace(),null,lc.getRequiredDocuments(),duplicate,errors.isEmpty(),errors,warnings,fields);}catch(RuntimeException ex){errors.add(readable(ex));return new SwiftImportPreview(type,null,null,null,null,null,null,null,null,null,List.of(),false,false,errors,warnings,fields);}}
 public Object execute(SwiftImportRequest request){SwiftImportPreview p=preview(request);if(!p.valid()){String msg=String.join(" ",p.errors());history.record(request.filename(),p.messageType(),p.reference(),"REJECTED",msg);throw new IllegalArgumentException(msg);}try{Object result=p.messageType().equals("MT707")?amendmentService.importMt707(request.rawMessage()):lcService.importMt700(request.rawMessage());history.record(request.filename(),p.messageType(),p.reference(),"SUCCESS","Import erfolgreich");return result;}catch(RuntimeException ex){history.record(request.filename(),p.messageType(),p.reference(),"REJECTED",readable(ex));throw ex;}}
 private List<SwiftFieldView> fields(String raw){List<String[]> parsed=new ArrayList<>();var matcher=FIELD.matcher(raw.strip());while(matcher.find())parsed.add(new String[]{matcher.group(1),matcher.group(2).trim()});Map<String,Long> counts=parsed.stream().collect(java.util.stream.Collectors.groupingBy(x->x[0],java.util.stream.Collectors.counting()));List<SwiftFieldView> result=new ArrayList<>();for(String[] item:parsed){String code=item[0],value=item[1],target=TARGETS.get(code),inferred=inferTarget(value);boolean duplicate=target!=null&&counts.getOrDefault(code,0L)>1;boolean misplaced=inferred!=null&&target!=null&&!inferred.equals(target);boolean unusual=value.isBlank()||duplicate||misplaced;String notice=value.isBlank()?"Das Feld ist leer.":duplicate?"Dieses Kernfeld kommt mehrfach vor und muss geprüft werden.":misplaced?"Der Inhalt deutet eher auf „"+TARGET_LABELS.get(inferred)+"“ hin.":target==null&&inferred!=null?"Der Inhalt könnte zu „"+TARGET_LABELS.get(inferred)+"“ gehören.":null;if(target==null&&inferred!=null){target=inferred;unusual=true;}String confidence=unusual||target==null?"LOW":"HIGH";String reason=target==null?"Für dieses SWIFT-Feld gibt es noch kein festes LC-Zielfeld.":unusual?"Inhaltsbasierter Prüfhinweis – manuelle Bestätigung erforderlich.":"Standardzuordnung für SWIFT-Feld :"+code+":";result.add(new SwiftFieldView(code,LABELS.getOrDefault(code,"Weiteres SWIFT-Feld"),value,target,target==null?"Noch nicht zugeordnet":TARGET_LABELS.get(target),confidence,reason,unusual,notice));}return result;}
 private String inferTarget(String value){String text=value==null?"":value.toLowerCase(Locale.ROOT);if(text.matches("(?s).*\\b(applicant|auftraggeber|antragsteller)\\b.*"))return "applicant";if(text.matches("(?s).*\\b(beneficiary|begünstigte[rrn]?)\\b.*"))return "beneficiary";if(text.matches("(?s).*\\b(expiry|expiration|ablaufdatum|valid until)\\b.*"))return "expiryDateAndPlace";if(text.matches("(?s).*\\b(latest shipment|späteste[rn]? versand)\\b.*"))return "latestShipmentDate";if(text.matches("(?s).*\\b(documents required|required documents|vorzulegende dokumente)\\b.*"))return "requiredDocuments";if(text.matches("(?s).*\\b(amount|betrag|total)\\b.*\\b(eur|usd|gbp|chf|jpy)\\b.*"))return "amountAndCurrency";return null;}
 private String requireRaw(SwiftImportRequest r){if(r==null||r.rawMessage()==null||r.rawMessage().isBlank())throw new IllegalArgumentException("Bitte eine SWIFT-Nachricht auswählen oder einfügen.");return r.rawMessage();}private String detect(String raw){return raw.matches("(?ms).*^:(26E|31E|46B):.*")?"MT707":"MT700";}private String readable(RuntimeException ex){return ex.getMessage()==null?"SWIFT-Nachricht konnte nicht gelesen werden.":ex.getMessage();}
}
